            float t = 0f;
            while (t < dur) { t += Time.deltaTime; yield return null; }
        }

        private IEnumerator WaitRealtime(float seconds)
        {
            float t = 0f;
            while (t < seconds) { t += Time.deltaTime; yield return null; }
        }

